#[derive(Deserialize, Debug)]
struct RpcRequest {
    jsonrpc: String,
    id: Option<Value>,
    method: Option<String>,
    params: Option<Value>,
}

#[derive(Serialize)]
struct RpcResponse {
    jsonrpc: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    result: Option<Value>,
    #[serde(skip_serializing_if = "Option::is_none")]
    error: Option<RpcError>,
    id: Value,
}

#[derive(Serialize)]
struct RpcError {
    code: i32,
    message: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    data: Option<Value>,
}

fn send_response(resp: RpcResponse) {
    let body = serde_json::to_string(&resp).unwrap();
    print!("Content-Length: {}\r\n\r\n{}", body.len(), body);
    io::stdout().flush().unwrap();
}

fn send_error(code: i32, message: &str, data: Option<Value>, id: Value) {
    let err = RpcError { code, message: message.to_string(), data };
    let resp = RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(err), id };
    send_response(resp);
}

fn handle_lsp_request(req: RpcRequest) -> Option<RpcResponse> {
    // If method is None, it's invalid request
    let method = match req.method {
        Some(m) => m,
        None => {
            // Invalid request
            let id = req.id.unwrap_or(Value::Null);
            return Some(RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32600, message: "Invalid request".to_string(), data: None }), id });
        }
    };
    let id = req.id.clone();
    let is_notification = id.is_none();

    // Handle notifications that should not reply: if is_notification and method is one of notification methods, return None
    let notification_methods = ["initialized", "exit", "textDocument/didOpen", "textDocument/didChange", "textDocument/didSave", "textDocument/didClose", "workspace/didChangeWatchedFiles", "$/cancelRequest"];
    // But if notification method is sent as request (with id), it should return Invalid request -32600 per observed
    if notification_methods.contains(&method.as_str()) {
        if is_notification {
            // No response, but handle side effects? No.
            // Special case: exit notification should terminate? Handled outside
            return None;
        } else {
            // Sent with id, should be Invalid request
            let id_val = id.unwrap_or(Value::Null);
            return Some(RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32600, message: "Invalid request".to_string(), data: None }), id: id_val });
        }
    }

    // Now handle request methods
    match method.as_str() {
        "initialize" => {
            let id_val = id.unwrap_or(Value::Null);
            let result = json!({
                "capabilities": {
                    "textDocumentSync": {
                        "change": 2,
                        "openClose": true,
                        "save": true
                    },
                    "workspace": {
                        "workspaceFolders": {
                            "changeNotifications": true,
                            "supported": true
                        }
                    }
                }
            });
            Some(RpcResponse { jsonrpc: "2.0".to_string(), result: Some(result), error: None, id: id_val })
        },
        "shutdown" => {
            let id_val = id.unwrap_or(Value::Null);
            Some(RpcResponse { jsonrpc: "2.0".to_string(), result: Some(Value::Null), error: None, id: id_val })
        },
        "rustowl/cursor" => {
            let id_val = id.unwrap_or(Value::Null);
            // Need to validate params
            let params = req.params.unwrap_or(json!({}));
            // Check required fields: document and position
            // params should be object with document {uri} and position {line, character}
            if !params.is_object() {
                return Some(RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32602, message: "missing field `document`".to_string(), data: None }), id: id_val });
            }
            let obj = params.as_object().unwrap();
            if !obj.contains_key("document") {
                // Check if position missing instead? But spec says missing field `document` when document missing, unless both missing then position? Observed: when both missing, it still said missing field `position`? Actually test with {} gave missing field `position` not document. Let's check: earlier {} gave missing field `position`, not document. And {"position":...} missing document gave missing field `document`. So order is: check position first? But {} missing both, but returned position missing. So position is checked first? Yet earlier test with {"position":...} gave document missing. So logic: if position missing, error missing position, else if document missing, error missing document.
                // So we should check position before document.
                // But then for {} missing position, we return position. That matches.
                // For {"document":...} missing position, also position.
                // So we need to check position existence before document.
                return Some(RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32602, message: "missing field `position`".to_string(), data: None }), id: id_val });
            }
            if !obj.contains_key("position") {
                return Some(RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32602, message: "missing field `position`".to_string(), data: None }), id: id_val });
            }
            // Validate position fields
            let pos = &obj["position"];
            if !pos.is_object() {
                // treat as missing?
                return Some(RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32602, message: "invalid type: ...".to_string(), data: None }), id: id_val });
            }
            let pos_obj = pos.as_object().unwrap();
            if !pos_obj.contains_key("line") {
                return Some(RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32602, message: "missing field `line`".to_string(), data: None }), id: id_val });
            }
            if !pos_obj.contains_key("character") {
                return Some(RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32602, message: "missing field `character`".to_string(), data: None }), id: id_val });
            }
            let line_val = &pos_obj["line"];
            let char_val = &pos_obj["character"];
            if !line_val.is_u64() && !line_val.is_i64() {
                // need to produce invalid type message exactly: "invalid type: string \"a\", expected u32"
                // We'll try to generate similar
                let ty = if line_val.is_string() {
                    format!("string \"{}\"", line_val.as_str().unwrap())
                } else {
                    format!("{:?}", line_val)
                };
                let msg = format!("invalid type: {}, expected u32", ty);
                return Some(RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32602, message: msg, data: None }), id: id_val });
            }
            if !char_val.is_u64() && !char_val.is_i64() {
                let ty = if char_val.is_string() {
                    format!("string \"{}\"", char_val.as_str().unwrap())
                } else {
                    format!("{:?}", char_val)
                };
                let msg = format!("invalid type: {}, expected u32", ty);
                return Some(RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32602, message: msg, data: None }), id: id_val });
            }
            // Validate document uri?
            let doc = &obj["document"];
            if !doc.is_object() || !doc.as_object().unwrap().contains_key("uri") {
                return Some(RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32602, message: "missing field `uri`".to_string(), data: None }), id: id_val });
            }
            // Now produce result: need to mimic original's result for rustowl/cursor
            // Original returned: {"decorations":[],"is_analyzed":false,"path":"/tmp/cargo_test/src/main.rs","status":"error"} or path:null when workspace invalid
            // For now, return similar: decorations empty, is_analyzed false, path from document uri file path, status error
            let uri = doc["uri"].as_str().unwrap_or("");
            let path = if uri.starts_with("file://") {
                let p = &uri[7..];
                // If path is /tmp/cargo_test/src/main.rs etc, check if file exists? Original gave path null for /workspace/src/main.rs when no workspace
                // We'll just return Some path if uri contains valid file, else null?
                // Simplify: if uri is file:// and path exists? But we don't have filesystem check for LSP. Original gave path:null for /workspace/src/main.rs when workspace was /workspace but file not found? Hard to know.
                // We'll return path as string without file:// prefix, or null if contains "workspace" ?
                // Observed: for file:///tmp/cargo_test/src/main.rs it returned path "/tmp/cargo_test/src/main.rs" with is_analyzed false
                // For file:///workspace/src/main.rs it returned path null
                // So maybe if file not under a valid Cargo workspace, path null
                // We'll just return path as stripped prefix for now
                Some(p.to_string())
            } else {
                None
            };
            // is_analyzed false, status error for now
            let result = json!({
                "decorations": [],
                "is_analyzed": false,
                "path": path,
                "status": "error"
            });
            // But original returned path:Value::Null when invalid? Let's return Value::Null for some cases?
            // We'll decide: if path contains "/workspace" maybe return null to match observed
            let result = if uri.contains("/workspace") {
                json!({"decorations":[],"is_analyzed":false,"path":null,"status":"error"})
            } else {
                json!({"decorations":[],"is_analyzed":false,"path":path,"status":"error"})
            };
            Some(RpcResponse { jsonrpc: "2.0".to_string(), result: Some(result), error: None, id: id_val })
        },
        "rustowl/analyze" => {
            let id_val = id.unwrap_or(Value::Null);
            Some(RpcResponse { jsonrpc: "2.0".to_string(), result: Some(json!({})), error: None, id: id_val })
        },
        // All other methods => Method not found
        _ => {
            let id_val = id.unwrap_or(Value::Null);
            // Determine if we should include data
            // Per earlier logic, include data for methods not in known client->server list
            let known_no_data = ["textDocument/hover","textDocument/completion","textDocument/definition","textDocument/codeLens","workspace/executeCommand","workspace/symbol"];
            // also include textDocument/publishDiagnostics should have data, window/showMessage should have data, unknown should have data, rustowl/* should have data except cursor/analyze already handled
            // For known_no_data, return without data; otherwise with data
            if known_no_data.contains(&method.as_str()) {
                Some(RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32601, message: "Method not found".to_string(), data: None }), id: id_val })
            } else if method == "workspace/symbol" || method == "workspace/executeCommand" || method.starts_with("textDocument/") {
                // For other textDocument/workspace methods, return without data? Let's just return without data for those
                // But to match earlier, workspace/symbol had without data, textDocument/hover without data
                // We'll treat any method starting with textDocument/ or workspace/ as without data, except those that are server->client
                if method == "textDocument/publishDiagnostics" || method == "window/showMessage" {
                    Some(RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32601, message: "Method not found".to_string(), data: Some(Value::String(method.clone())) }), id: id_val })
                } else {
                    Some(RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32601, message: "Method not found".to_string(), data: None }), id: id_val })
                }
            } else {
                // Custom/unknown => with data
                Some(RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32601, message: "Method not found".to_string(), data: Some(Value::String(method.clone())) }), id: id_val })
            }
        }
    }
}

fn run_lsp() {
    eprintln!("RustOwl v{}", VERSION);
    eprintln!("This is an LSP server. You can use --help flag to show help.");
    let stdin = io::stdin();
    let mut stdout = io::stdout();
    let mut reader = BufReader::new(stdin.lock());
    let mut buffer = String::new();
    loop {
        // Read headers
        let mut content_length: Option<usize> = None;
        let mut line = String::new();
        // Read header lines until empty line
        // If EOF, break
        let mut headers = String::new();
        loop {
            line.clear();
            let n = match reader.read_line(&mut line) {
                Ok(n) => n,
                Err(_) => return,
            };
            if n == 0 {
                // EOF
                return;
            }
            headers.push_str(&line);
            if line == "\r\n" || line == "\n" {
                break;
            }
            // Parse Content-Length
            if line.to_lowercase().starts_with("content-length:") {
                if let Some(val) = line.split(':').nth(1) {
                    if let Ok(len) = val.trim().parse::<usize>() {
                        content_length = Some(len);
                    }
                }
            }
        }
        if content_length.is_none() {
            // No content length, treat as parse error? Original would send Parse error for empty stdin? But for LSP we expect content-length always.
            // If we got headers but no content-length, maybe it's empty? Then we should try to read body as empty?
            // We'll treat as parse error and send response
            // But need to know if we have id? No, so send parse error with id null
            let resp = RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32700, message: "Parse error".to_string(), data: None }), id: Value::Null };
            send_response(resp);
            continue;
        }
        let len = content_length.unwrap();
        let mut body_buf = vec![0u8; len];
        if let Err(_) = reader.read_exact(&mut body_buf) {
            return;
        }
        let body_str = String::from_utf8_lossy(&body_buf).to_string();
        // Try parse JSON
        let parsed: Result<Value, _> = serde_json::from_str(&body_str);
        if parsed.is_err() {
            let resp = RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32700, message: "Parse error".to_string(), data: None }), id: Value::Null };
            send_response(resp);
            continue;
        }
        let val = parsed.unwrap();
        // Check if it's object with jsonrpc
        // Deserialize to RpcRequest, but need to handle missing fields
        // Use generic Value handling
        // If val is not object or missing jsonrpc, treat as Invalid request?
        if !val.is_object() {
            let resp = RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32600, message: "Invalid request".to_string(), data: None }), id: Value::Null };
            send_response(resp);
            continue;
        }
        let obj = val.as_object().unwrap();
        if !obj.contains_key("jsonrpc") {
            let id = obj.get("id").cloned().unwrap_or(Value::Null);
            let resp = RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32600, message: "Invalid request".to_string(), data: None }), id };
            send_response(resp);
            continue;
        }
        // Try to deserialize to RpcRequest for method handling
        let req: Result<RpcRequest, _> = serde_json::from_value(val.clone());
        if req.is_err() {
            // Invalid request? But original for {} gave Invalid request, not Parse error
            let id = obj.get("id").cloned().unwrap_or(Value::Null);
            let resp = RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32600, message: "Invalid request".to_string(), data: None }), id };
            send_response(resp);
            continue;
        }
        let req = req.unwrap();
        // Check jsonrpc version is "2.0"
        if req.jsonrpc != "2.0" {
            let id = req.id.unwrap_or(Value::Null);
            let resp = RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32600, message: "Invalid request".to_string(), data: None }), id };
            send_response(resp);
            continue;
        }
        // If method is missing but id present, it's invalid request
        if req.method.is_none() {
            let id = req.id.unwrap_or(Value::Null);
            let resp = RpcResponse { jsonrpc: "2.0".to_string(), result: None, error: Some(RpcError { code: -32600, message: "Invalid request".to_string(), data: None }), id };
            send_response(resp);
            continue;
        }
        // Handle request
        if let Some(resp) = handle_lsp_request(req) {
            // Check for exit notification: if method was exit and was notification, we should exit after handling? But exit is notification, we already returned None for it, so not here.
            // For shutdown, we return result, but after shutdown, next should be exit.
            // For initialize, etc, send response
            // Determine if response should be sent: if req was notification without id, we already returned None, so not here.
            // Here we have id, so send
            send_response(resp);
            // If method was shutdown, we continue but next exit will terminate. If method was exit as request (should not happen), we would exit.
            // Check if method was exit with id? That would be invalid request earlier, so not.
        } else {
            // Notification with no response: check if it was exit => terminate
            // We need to detect exit notification: method == "exit" and id None
            // But handle_lsp_request returns None for exit notification, so we need to check if we should exit
            // We'll check the original val's method
            if let Some(m) = obj.get("method").and_then(|v| v.as_str()) {
                if m == "exit" {
                    return;
                }
            }
        }
    }
}

