                            let mut sub_cmd = make_command(&bin_name);
                            if let Some(clean_cmd) = sub_cmd.find_subcommand_mut("clean") {
                                let mut buf = Vec::new();
                                clean_cmd.write_help(&mut buf).unwrap();
                                print!("{}", String::from_utf8(buf).unwrap());
                            }
                            std::process::exit(0);
                        }
                        // clean does nothing
                        std::process::exit(0);
                    },
                    "toolchain" => {
                        if sub_matches.get_flag("help") {
                            let mut sub_cmd = make_command(&bin_name);
                            if let Some(tc_cmd) = sub_cmd.find_subcommand_mut("toolchain") {
                                let mut buf = Vec::new();
                                tc_cmd.write_help(&mut buf).unwrap();
                                print!("{}", String::from_utf8(buf).unwrap());
                            }
                            std::process::exit(0);
                        }
                        if let Some((tc_sub, tc_matches)) = sub_matches.subcommand() {
                            match tc_sub {
                                "install" => {
                                    if tc_matches.get_flag("help") {
                                        let mut sub_cmd = make_command(&bin_name);
                                        if let Some(tc) = sub_cmd.find_subcommand_mut("toolchain") {
                                            if let Some(inst) = tc.find_subcommand_mut("install") {
                                                let mut buf = Vec::new();
                                                inst.write_help(&mut buf).unwrap();
                                                print!("{}", String::from_utf8(buf).unwrap());
                                            }
                                        }
                                        std::process::exit(0);
                                    }
                                    let path = tc_matches.get_one::<String>("path").cloned();
                                    let skip = tc_matches.get_flag("skip-rustowl-toolchain");
                                    let code = handle_toolchain_install(path, skip);
                                    std::process::exit(code);
                                },
                                "uninstall" => {
                                    if tc_matches.get_flag("help") {
                                        let mut sub_cmd = make_command(&bin_name);
                                        if let Some(tc) = sub_cmd.find_subcommand_mut("toolchain") {
                                            if let Some(un) = tc.find_subcommand_mut("uninstall") {
                                                let mut buf = Vec::new();
                                                un.write_help(&mut buf).unwrap();
                                                print!("{}", String::from_utf8(buf).unwrap());
                                            }
                                        }
                                        std::process::exit(0);
                                    }
                                    let code = handle_toolchain_uninstall();
                                    std::process::exit(code);
                                },
                                "help" => {
                                    // toolchain help subcommand: print help for toolchain or its subcommands
                                    // The "help" subcommand under toolchain is auto-generated by clap? But we added explicit help subcommand.
                                    // We'll handle help display for toolchain help
                                    let mut sub_cmd = make_command(&bin_name);
                                    if let Some(tc) = sub_cmd.find_subcommand_mut("toolchain") {
                                        let mut buf = Vec::new();
                                        tc.write_help(&mut buf).unwrap();
                                        print!("{}", String::from_utf8(buf).unwrap());
                                    }
                                    std::process::exit(0);
                                },
                                _ => {
                                    // unknown, but clap should have errored earlier
                                    eprintln!("error: unrecognized subcommand '{}'", tc_sub);
                                    std::process::exit(2);
                                }
                            }
                        } else {
                            // No subcommand under toolchain, print help?
                            let mut sub_cmd = make_command(&bin_name);
                            if let Some(tc) = sub_cmd.find_subcommand_mut("toolchain") {
                                let mut buf = Vec::new();
                                tc.write_help(&mut buf).unwrap();
                                print!("{}", String::from_utf8(buf).unwrap());
                            }
                            std::process::exit(0);
                        }
                    },
                    "completions" => {
                        if sub_matches.get_flag("help") {
                            let mut sub_cmd = make_command(&bin_name);
                            if let Some(comp) = sub_cmd.find_subcommand_mut("completions") {
                                let mut buf = Vec::new();
                                comp.write_help(&mut buf).unwrap();
                                print!("{}", String::from_utf8(buf).unwrap());
