                            std::process::exit(2);
                        }
                    },
                    "help" => {
                        // help subcommand: print help for given command if any, else top help
                        // The help subcommand may have args after it (the command to show help for)
                        // In our Command, help subcommand has no args defined, so it will capture remaining args as values?
                        // Need to handle: `help check` etc. clap's help subcommand automatically handles, but we disabled help flag for it?
                        // Instead, we need to manually check remaining args from original args
                        // args is full args vector, we can parse help args
                        // Find position of "help" in args
                        let help_idx = args.iter().position(|a| a == "help").unwrap_or(0);
                        let help_args = &args[help_idx+1..];
                        if help_args.is_empty() {
                            let mut buf = Vec::new();
                            cmd.write_help(&mut buf).unwrap();
                            print!("{}", String::from_utf8(buf).unwrap());
                            std::process::exit(0);
                        } else {
                            // Try to find subcommand help
                            // For simplicity, handle first level: check, clean, toolchain, completions
                            // For toolchain install etc, need deeper
                            let first = &help_args[0];
                            // Find subcommand
                            let mut found_cmd: Option<Command> = None;
                            // Clone cmd to search
                            let mut base = make_command(&bin_name);
                            if let Some(sub) = base.find_subcommand(first) {
                                if help_args.len() == 1 {
                                    let mut buf = Vec::new();
                                    let mut sc = sub.clone();
                                    sc.write_help(&mut buf).unwrap();
                                    print!("{}", String::from_utf8(buf).unwrap());
                                    std::process::exit(0);
                                } else {
                                    // Try second level, e.g., toolchain install
                                    let second = &help_args[1];
                                    if let Some(sub2) = sub.find_subcommand(second) {
                                        let mut buf = Vec::new();
                                        let mut sc2 = sub2.clone();
                                        sc2.write_help(&mut buf).unwrap();
                                        print!("{}", String::from_utf8(buf).unwrap());
                                        std::process::exit(0);
                                    } else {
                                        // Unknown help target, just print top help
                                        let mut buf = Vec::new();
                                        base.write_help(&mut buf).unwrap();
                                        print!("{}", String::from_utf8(buf).unwrap());
                                        std::process::exit(0);
                                    }
                                }
                            } else {
                                let mut buf = Vec::new();
                                base.write_help(&mut buf).unwrap();
                                print!("{}", String::from_utf8(buf).unwrap());
                                std::process::exit(0);
                            }
                        }
                    },
                    _ => {
                        // Unknown subcommand - clap should have handled, but just in case
                        eprintln!("error: unrecognized subcommand '{}'", sub_name);
                        std::process::exit(2);
                    }
                }
            } else {
                // No subcommand: LSP mode or version/help already handled
                // Also need to consider quiet and stdio flags - they don't affect LSP except startup message already handled
                run_lsp();
            }
        },
        Err(e) => {
            // Clap error: print to stderr and exit with code 2 (or e.exit_code())
            // Use e.exit_code() but ensure it matches original: for missing required args etc, code 2
            let code = e.exit_code();
            e.print().unwrap();
            std::process::exit(code);
        }
    }
}
